// Sea-floor deposits (docs/design.md, "Deep sea"): five full-cube blocks plus one loose piece, placed by the worldgen in
// kubejs/data/pack/worldgen/*/ocean/. Drops are GregTech raw ores (kubejs/data/pack/loot_table/blocks/).
// Textures and the two non-vanilla models are generated by tools/sea_textures.py (kubejs/assets/pack/).
//
// Full cubes, on purpose: a block that replaces a TFC salt water source must not be waterloggable (a vanilla waterlogged
// state would put vanilla water into a TFC ocean). The loose nodule is TFC's own ground-cover block, which holds TFC fluids.
// Vents' smoke, sound and bubbles are client-side: kubejs/client_scripts/sea_vents.js. No random tick here any more.

const $SoundType = Java.loadClass('net.minecraft.world.level.block.SoundType')

StartupEvents.registry('block', event => {
  // Black smoker: dark sulfide, rusty oxide; the tip face is fullbright (neoforge_data in the model) with a hot rim.
  event.create('pack:sulfide_chimney')
    .hardness(4.0).resistance(6.0)
    .soundType($SoundType.DEEPSLATE)
    .requiresTool()
    .tagBlock('minecraft:mineable/pickaxe')
    .lightLevel(0.5)
    .parentModel('pack:block/sulfide_chimney_shape')
    .textures({ side: 'pack:block/sulfide_chimney', top: 'pack:block/sulfide_chimney_top', bottom: 'pack:block/sulfide_chimney' })
    .displayName('Sulfide Chimney')

  // White smoker: anhydrite (gypsum stands in) and a little zinc sulfide. Barite would be as real but its barium would pull the superconductors forward.
  event.create('pack:anhydrite_chimney')
    .hardness(3.0).resistance(5.0)
    .soundType($SoundType.CALCITE)
    .requiresTool()
    .tagBlock('minecraft:mineable/pickaxe')
    .lightLevel(0.4)
    .parentModel('pack:block/anhydrite_chimney_shape')
    .textures({ side: 'pack:block/anhydrite_chimney', top: 'pack:block/anhydrite_chimney_top', bottom: 'pack:block/anhydrite_chimney' })
    .displayName('Anhydrite Chimney')

  event.create('pack:sulfide_mound')
    .hardness(3.0).resistance(5.0)
    .soundType($SoundType.DEEPSLATE)
    .requiresTool()
    .tagBlock('minecraft:mineable/pickaxe')
    .parentModel('minecraft:block/cube_all')
    .textures({ all: 'pack:block/sulfide_mound' })
    .displayName('Sulfide Mound')

  // Mud with nodules lying on it. Shovel, so a diver can sweep a field quickly.
  event.create('pack:nodule_bed')
    .hardness(1.0).resistance(1.0)
    .soundType($SoundType.GRAVEL)
    .tagBlock('minecraft:mineable/shovel')
    .parentModel('minecraft:block/cube_bottom_top')
    .textures({ top: 'pack:block/nodule_bed', side: 'pack:block/nodule_bed_side', bottom: 'pack:block/nodule_bed_bottom' })
    .displayName('Nodule Bed')

  event.create('pack:mn_crust')
    .hardness(4.5).resistance(6.0)
    .soundType($SoundType.STONE)
    .requiresTool()
    .tagBlock('minecraft:mineable/pickaxe')
    .parentModel('minecraft:block/cube_all')
    .textures({ all: 'pack:block/mn_crust' })
    .displayName('Manganese Crust')

  // A loose manganese nodule: TFC's ground-cover block (kubejs-tfc 'tfc:groundcover'), fluid-loggable with TFC salt water
  // (GroundcoverBlock.FLUID = TFCBlockStateProperties.WATER: empty, water, salt water). Right-click with an empty hand
  // picks it up through its loot table (kubejs/data/pack/loot_table/blocks/nodule.json), like a loose rock.
  event.create('pack:nodule', 'tfc:groundcover')
    .ore() // the small hit box
    .soundType($SoundType.GRAVEL)
    .parentModel('pack:block/nodule_shape')
    .textures({ all: 'pack:block/nodule', particle: 'pack:block/nodule' })
    .displayName('Manganese Nodule')
})
